import { crc32, deflateRawSync } from 'node:zlib';

// Small, local export bundles. Entry names are generated by OpenSix.
export function zipOutput(files) {
  const local = [], directory = [];
  let offset = 0;
  for (const [name, data] of files) {
    const filename = Buffer.from(name, 'ascii');
    const compressed = deflateRawSync(data);
    const packed = compressed.length < data.length ? compressed : data;
    const method = packed === data ? 0 : 8;
    const checksum = crc32(data);
    const header = Buffer.alloc(30);
    header.writeUInt32LE(0x04034b50);
    header.writeUInt16LE(20,4);
    header.writeUInt16LE(method,8);
    header.writeUInt16LE(33,12); // 1980-01-01, reproducible.
    header.writeUInt32LE(checksum,14);
    header.writeUInt32LE(packed.length,18);
    header.writeUInt32LE(data.length,22);
    header.writeUInt16LE(filename.length,26);
    const central = Buffer.alloc(46);
    central.writeUInt32LE(0x02014b50);
    central.writeUInt16LE(20,4);
    header.copy(central,6,4,28);
    central.writeUInt32LE(offset,42);
    local.push(header,filename,packed);
    directory.push(central,filename);
    offset += header.length + filename.length + packed.length;
  }
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50);
  end.writeUInt16LE(files.size,8);
  end.writeUInt16LE(files.size,10);
  end.writeUInt32LE(directory.reduce((n,part)=>n+part.length,0),12);
  end.writeUInt32LE(offset,16);
  return Buffer.concat([...local,...directory,end]);
}
